files.database/027_AddCustomerNotes.sql:
-- Migración 027: agrega columna Notes a Customers
BEGIN TRANSACTION;

IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID('Customers') AND name = 'Notes')
BEGIN
    ALTER TABLE Customers ADD Notes NVARCHAR(500) NULL;
    PRINT 'Migración 027: columna Notes agregada a Customers';
END

COMMIT TRANSACTION;

files.database/027_FixOrderStatusDefault.sql:
-- Migración 027: corrige default de Status en Orders
BEGIN TRANSACTION;

IF EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID('Orders') AND name = 'Status')
BEGIN
    ALTER TABLE Orders ADD CONSTRAINT DF_Orders_Status DEFAULT 'Pending' FOR Status;
    PRINT 'Migración 027: default Pending aplicado a Orders.Status';
END

COMMIT TRANSACTION;

files.database/031_NormalizeTicketSeverity.sql:
-- Migracion 031: normaliza Severity a la nueva tabla TicketPriorities y elimina la columna vieja
ALTER TABLE Tickets ADD PriorityId INT NULL;

UPDATE Tickets SET PriorityId = (SELECT Id FROM TicketPriorities WHERE Name = Tickets.Severity);

DELETE FROM Tickets WHERE PriorityId IS NULL;

ALTER TABLE Tickets ALTER COLUMN PriorityId INT NOT NULL;

ALTER TABLE Tickets DROP COLUMN Severity;

files.database/031_AddPriorityToTickets.sql:
-- Migración 031: agrega Priority a Tickets y backfillea valores existentes
BEGIN TRANSACTION;

IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID('Tickets') AND name = 'Priority')
BEGIN
    ALTER TABLE Tickets ADD Priority INT NOT NULL DEFAULT 3;
    PRINT 'Migración 031: columna Priority agregada a Tickets';
END

UPDATE Tickets SET Priority = 1 WHERE Severity = 'Critical';
UPDATE Tickets SET Priority = 2 WHERE Severity = 'High';
PRINT 'Migración 031: backfill de Priority según Severity completado';

COMMIT TRANSACTION;

files.database/032_AddTicketTags.sql:
-- Migración 032: tabla de tags + seed inicial — todo aditivo e idempotente, SIN transacción
IF OBJECT_ID('TicketTags', 'U') IS NULL
BEGIN
    CREATE TABLE TicketTags (
        Id INT IDENTITY(1,1) PRIMARY KEY,
        Name NVARCHAR(50) NOT NULL,
        Color NVARCHAR(7) NOT NULL DEFAULT '#808080'
    );
END

IF NOT EXISTS (SELECT 1 FROM TicketTags WHERE Name = 'urgente')
    INSERT INTO TicketTags (Name, Color) VALUES ('urgente', '#d00000');

IF NOT EXISTS (SELECT 1 FROM TicketTags WHERE Name = 'cliente-vip')
    INSERT INTO TicketTags (Name, Color) VALUES ('cliente-vip', '#7b2d8e');
